      `<g clip-path="url(#NS-${id})">${label(id,x,y,value,size,fill,brand?'style="font-family:Oswald,sans-serif;font-weight:700"':'')}</g>`+
      `<circle data-part="${id}-pen" cx="${x}" cy="${y-size*.32}" r="${Math.max(1.6,size*.035)}" fill="${graphite}" opacity="0"/>`;
