let pulseSamples;
function getPulseSamples(){
  if(!pulseSamples) pulseSamples=Uint8Array.from(global.atob(pulseBaked.replace(/\s/g,'')),c=>c.charCodeAt(0));
  return pulseSamples;
}
reg('data-pulse',make=>{
  const samples=getPulseSamples(),scale=.22,stride=193;
  const unit=(i,n,start=-Math.PI/2)=>{const a=start+i/n*Math.PI*2;return [Math.cos(a),Math.sin(a)];};
  const bands=Array.from({length:64},(_,i)=>[unit(i,128),unit(127-i,128)]);
  const dots=Array.from({length:220},(_,i)=>unit(i,220,0));
  const waveX=Array.from({length:128},(_,i)=>(68+i/127*504).toFixed(3));
  // 每个频段画一对镜像条；外圈粒点按透明度合并为八条路径，减少逐帧节点修改。
  const s=make(`<g transform="translate(320 155)"><g data-part="spectrum" fill="none" stroke-width="1.32" stroke-linecap="round">`+
    list(64,i=>`<path data-part="f${i}" data-spectrum-band="${i}" stroke="var(--ink)"/>`)+
    `</g><g data-part="particles" fill="var(--ink)">`+
    list(8,i=>`<path data-part="particles${i}" opacity="${.1+i*.4/7}"/>`)+
    `</g><circle data-part="inner" fill="none" stroke="var(--ink)" stroke-width=".44" opacity=".5"/>`+
    text('rate',0,-2.64,'44.1','title')+
    `<text x="0" y="12.76" text-anchor="middle" fill="var(--muted)" font-size="${font('micro')}" font-weight="700" letter-spacing="1.1">kHz · STEREO</text></g>`+
    `<text x="68" y="293" fill="var(--muted)" font-size="${font('micro')}" font-weight="700" letter-spacing=".88">WAVEFORM · LIVE</text>`+
    `<path data-part="wave-soft" fill="none" stroke="var(--ink)" stroke-width="1.76" opacity=".08"/>`+
    `<path data-part="wave" fill="none" stroke="var(--ink)" stroke-width=".55" opacity=".85"/>`);
  const point=(v,r)=>`${(v[0]*r).toFixed(3)} ${(v[1]*r).toFixed(3)}`;
  let lastFrame=-1;
  return (p,state)=>{
    const frame=Math.round(p*180),offset=frame*stride;
    if(frame!==lastFrame){
      const radius=(175+samples[offset+192]/255*18)*scale;
      for(let i=0;i<64;i++){
        const v=samples[offset+i]/255,end=radius+(14+Math.pow(v,1.7)*300)*scale;
        s('f'+i,{d:bands[i].map(u=>`M${point(u,radius)}L${point(u,end)}`).join(''),
          stroke:v>.72?'var(--accent)':'var(--ink)','stroke-opacity':.35+v*.6});
      }
      const clusters=Array.from({length:8},()=>[]);
      for(let i=0;i<220;i++){
        const v=samples[offset+(i*7)%64]/255,r=(520+v*40)*scale,u=dots[i];
        const x=(u[0]*r-.33).toFixed(3),y=(u[1]*r-.33).toFixed(3);
        clusters[Math.round(v*7)].push(`M${x} ${y}h.66v.66h-.66Z`);
      }
      clusters.forEach((path,i)=>s('particles'+i,{d:path.join('')}));
      s('inner',{r:radius-16*scale});
      const wave=waveX.map((x,i)=>`${i?'L':'M'}${x} ${(318+(samples[offset+64+i]-128)/127*110*scale).toFixed(3)}`).join('');
      s('wave-soft',{d:wave});s('wave',{d:wave});
      lastFrame=frame;
    }
    // 连续播放时沿用累计时间，环形转动不会在每次循环时倒回。
    const seconds=(state?.elapsed??p*3000)/1000;
    s('spectrum',{transform:`rotate(${seconds*.15*180/Math.PI})`});
    s('particles',{transform:`rotate(${-seconds*.4*180/Math.PI})`});
  };
});
